mapper.select:
select en.id, en.user_id as userId, en.type, en.source_user_id as sourceUserId, case when en.type = 6 then '系统通知' else u.name end as sourceUserName, case when en.type = 6 then null else u.avatar end as sourceUserAvatar, en.post_id as postId, en.comment_id as commentId, en.content, en.is_read as isRead, en.create_time as createTime from experience_notification en left join user u on en.source_user_id = u.id left join experience_post ep on en.post_id = ep.id left join experience_comment ec on en.comment_id = ec.id where en.user_id = #{userId}
and en.type = #{type}
order by en.create_time desc
